SELECT m.id, m.create_user_id, m.create_user_name, m.create_time, m.update_user_id, m.update_user_name, m.update_time, m.version, m.is_deleted, m.type, COALESCE(NULLIF(m.data_json, ''), m.remark, '') AS data_json, m.remark FROM message m LEFT JOIN message_user_read mur ON m.id = mur.message_id AND mur.is_deleted = FALSE AND mur.user_id = #{param.userId} WHERE M.is_deleted = FALSE
AND m.type = #{param.type}
AND COALESCE(mur.is_read, FALSE) = FALSE AND ( (m.type = 'sys' AND m.application IN ('PDA', 'PC')) OR ( m.type != 'sys' AND mur.user_id IS NOT NULL
AND m.application IN
#{app}
) ) AND (m.notice_time IS NULL OR m.notice_time <= NOW()) AND (m.expire_time IS NULL OR m.expire_time >= NOW())

SELECT m.id, m.create_user_id, m.create_user_name, m.create_time, m.update_user_id, m.update_user_name, m.update_time, m.version, m.is_deleted, m.type, COALESCE(NULLIF(m.data_json, ''), m.remark, '') AS data_json, m.remark, mur.is_read FROM message m LEFT JOIN message_user_read mur ON m.id = mur.message_id AND mur.is_deleted = FALSE AND mur.user_id = #{param.userId} WHERE m.is_deleted = FALSE
AND m.type = #{param.type}
AND COALESCE(mur.is_read, FALSE) = FALSE AND ( (m.type = 'sys' AND m.application IN ('PDA', 'PC')) OR ( m.type != 'sys' AND mur.user_id IS NOT NULL
AND m.application IN
#{app}
) ) AND (m.notice_time IS NULL OR m.notice_time <= NOW()) AND (m.expire_time IS NULL OR m.expire_time >= NOW()) ORDER BY m.create_time DESC limit #{param.pageSize} offset #{param.offSet}

SELECT m."type",count(*) count,max(m.create_time) latestTime FROM message m LEFT JOIN message_user_read mur ON m.id = mur.message_id AND mur.is_deleted = FALSE AND mur.user_id = #{param.userId} WHERE m.is_deleted = FALSE
AND m.type = #{param.type}
AND COALESCE(mur.is_read, FALSE) = FALSE AND ( (m.type = 'sys' AND m.application IN ('PDA', 'PC')) OR ( m.type != 'sys' AND mur.user_id IS NOT NULL
AND m.application IN
#{app}
) ) AND (m.notice_time IS NULL OR m.notice_time <= NOW()) AND (m.expire_time IS NULL OR m.expire_time >= NOW()) GROUP BY m."type"

SELECT m.id, m.upgrade_version as upgradeVersion, m.data_json as dataJson, m.create_user_id as createUserId, m.create_user_name as createUserName, m.create_time as createTime, m.expire_time as expireTime FROM message m WHERE m.is_deleted = FALSE AND m.application = 'sysVersion'
${params.permissionSql}
ORDER BY m.create_time DESC

SELECT m.id, m.notice_title, m.type, COALESCE(NULLIF(m.data_json, ''), m.remark, '') AS data_json, m.create_time as noticeTime, COALESCE(mur.is_read, FALSE) as isRead FROM message m LEFT JOIN message_user_read mur on m.id = mur.message_id AND mur.is_deleted = FALSE AND mur.user_id = #{userId} WHERE m.is_deleted = FALSE AND m.application = 'PC'
AND m.id = #{params.id}
AND m.notice_title LIKE CONCAT('%', #{params.noticeTitle}, '%')
AND m.type = #{params.type}
${params.permissionSql}
ORDER BY m.create_time DESC

SELECT m.id, m.upgrade_version as upgradeVersion, m.data_json, m.create_time as noticeTime, COALESCE(mur.is_read, FALSE) as isRead FROM message m LEFT JOIN message_user_read mur on m.id = mur.message_id AND mur.is_deleted = FALSE AND mur.user_id = #{userId} WHERE m.is_deleted = FALSE AND m.application = 'sysVersion'
${params.permissionSql}
ORDER BY m.create_time DESC
